class ConfiguredReferenceExecutor(ReferenceExtensionExecutor):
    """Provide output identities through the extension's configuration hook."""

    @classmethod
    def get_output_ports(
        cls, config: dict[str, Any] | None = None,
    ) -> tuple[WorkflowNodeOutputPort, ...]:
        """Build ports only when callers explicitly provide the configuration."""
        branches = (config or {})["branches"]
        return tuple(
            WorkflowNodeOutputPort(branch, branch.title(), max_connections=None)
            for branch in branches
        )


class TestGetAuthoringReferenceView(BloomerpMcpViewTestCase):
    """Read compact indexes and targeted definitions over the real MCP transport."""

    view_name = "get_authoring_reference"

    def compact_index_is_live(self, response: HttpResponse) -> bool:
        """Require current identities and descriptions without detailed contracts."""
        document = response.json()["result"]["structuredContent"]
        expected = (
            {key for key, _ in TILE_TYPE_REGISTRY.items()}
            if document["kind"] == "tile"
            else {definition.id for definition in WORKFLOW_NODE_REGISTRY.values()}
        )
        return (
            set(document) == {"kind", "types"}
            and {item["type"] for item in document["types"]} == expected
            and all(set(item) == {"type", "name", "description"} for item in document["types"])
        )

    def tile_contract_retains_nested_schema(self, response: HttpResponse) -> bool:
        """Ensure one requested schema retains the definitions its references need."""
        document = response.json()["result"]["structuredContent"]
        schema = document["definition"]["config_schema"]
        Draft202012Validator.check_schema(schema)
        expected = TILE_TYPE_REGISTRY.get("LINKS_TILE").model.model_json_schema(mode="validation")
        return (
            document["definition"]["type"] == "LINKS_TILE"
            and "types" not in document
            and schema == expected
            and "Link" in schema["$defs"]
            and schema["properties"]["links"]["items"]["$ref"] == "#/$defs/Link"
            and "mutation catalog" in document["instructions"]
        )

    def object_condition_has_string_branches(self, response: HttpResponse) -> bool:
        """Require both branch identities, connection limits and clear edge guidance."""
        definition = response.json()["result"]["structuredContent"]["definition"]
        connections = definition["connections"]
        return (
            definition["sub_type"] == "OBJECT_IF_CONDITION"
            and definition["type"] == "FLOW"
            and {field["name"] for field in definition["parameters"]} >= {"content_type_id", "filters"}
            and definition["output_ports"] == [
                {"id": "true", "label": "True", "max_connections": None},
                {"id": "false", "label": "False", "max_connections": None},
            ]
            and connections["multiple_outputs"] is True
            and connections["output_port_schema"] == {"type": "string", "enum": ["true", "false"]}
            and "not a boolean" in connections["instructions"]
        )

    def unknown_type_has_recovery(self, response: HttpResponse) -> bool:
        """Require an actionable error directing the caller to the compact index."""
        result = response.json()["result"]
        text = " ".join(item.get("text", "") for item in result["content"])
        return "Omit type" in text and "suggested_arguments" in text

    def permission_for_scenario(self, scenario: McpRequestScenario) -> Permission:
        """Resolve the appropriate authoring permission for the scenario's kind."""
        model = Workspace if scenario.arguments["kind"] == "tile" else Workflow
        return Permission.objects.get(
            content_type=ContentType.objects.get_for_model(model),
            codename=f"view_{model._meta.model_name}",
        )

    def grant_user_permission(self, scenario: McpRequestScenario) -> None:
        """Grant direct read access to the requested authoring domain."""
        scenario.user.user_permissions.add(self.permission_for_scenario(scenario))

    def grant_group_permission(self, scenario: McpRequestScenario) -> None:
        """Grant read access through an ordinary Django group."""
        group = Group.objects.create(name="Authoring reference readers")
        group.permissions.add(self.permission_for_scenario(scenario))
        scenario.user.groups.add(group)

    def grant_policy_permission(self, scenario: McpRequestScenario) -> None:
        """Grant read access through an assigned policy's global permissions."""
        permission = self.permission_for_scenario(scenario)
        policy = Policy.objects.create(
            name="Authoring reference policy",
            row_policy=RowPolicy.objects.create(content_type=permission.content_type),
            field_policy=FieldPolicy.objects.create(
                name="Authoring reference fields", content_type=permission.content_type, rule={},
            ),
        )
        policy.global_permissions.add(permission)
        policy.users.add(scenario.user)

    def get_test_scenarios(self) -> list[McpRequestScenario]:
        """Cover precise contracts, input errors and both domains' permission paths."""
        scenarios = [
            McpRequestScenario(
                name="Returns one tile schema with resolvable nested definitions",
                user=self.admin_user, arguments={"kind": "tile", "type": "LINKS_TILE"},
                expected=ExpectedResult(response_validators=[self.mcp_is_error(False), self.tile_contract_retains_nested_schema]),
            ),
            McpRequestScenario(
                name="Object condition advertises both exact string output ports",
                user=self.admin_user, arguments={"kind": "workflow_node", "type": "OBJECT_IF_CONDITION"},
                expected=ExpectedResult(response_validators=[self.mcp_is_error(False), self.object_condition_has_string_branches]),
            ),
            McpRequestScenario(
                name="Unknown type explains how to discover installed identities",
                user=self.admin_user, arguments={"kind": "tile", "type": "NOT_INSTALLED"},
                expected=ExpectedResult(response_validators=[self.mcp_is_error(), self.unknown_type_has_recovery]),
            ),
            McpRequestScenario(
                name="Anonymous lookup requires authentication",
                arguments={"kind": "tile"},
                expected=ExpectedResult(
                    status_code=200 if oauth_enabled() else 401,
                    response_validators=self.mcp_is_error() if oauth_enabled() else None,
                ),
            ),
        ]
        for kind in ("tile", "workflow_node"):
            scenarios.extend([
                McpRequestScenario(
                    name=f"Superuser reads compact live {kind} index", user=self.admin_user,
                    arguments={"kind": kind},
                    expected=ExpectedResult(response_validators=[self.mcp_is_error(False), self.compact_index_is_live]),
                ),
                McpRequestScenario(
                    name=f"User without {kind} access is denied", user=self.normal_user,
                    arguments={"kind": kind},
                    expected=ExpectedResult(response_validators=self.mcp_is_error()),
                ),
            ])
            for label, prepare in (
                ("Direct", self.grant_user_permission),
                ("Group", self.grant_group_permission),
                ("Policy", self.grant_policy_permission),
            ):
                scenarios.append(McpRequestScenario(
                    name=f"{label} permission grants {kind} authoring access",
                    user=self.normal_user, prepare=prepare, arguments={"kind": kind},
                    expected=ExpectedResult(response_validators=[self.mcp_is_error(False), self.compact_index_is_live]),
                ))
        for arguments in (
            {}, {"kind": "unknown"}, {"kind": "tile", "type": ""},
            {"kind": "tile", "parameters": {}},
            {"kind": "workflow_node", "parameters": {}},
            {"kind": "workflow_node", "type": "OBJECT_IF_CONDITION", "parameters": []},
        ):
            scenarios.append(McpRequestScenario(
                name=f"Rejects invalid authoring selector {arguments}",
                user=self.admin_user, arguments=arguments,
                expected=ExpectedResult(response_validators=self.mcp_is_error()),
            ))
        return scenarios

    def test_registration_advertises_safe_extensible_inputs(self) -> None:
        """Use case: An agent discovers the tool and its selectable arguments.
        Expected result: Metadata declares a read-only tool without fixed type identities.
        """
        contract = self.get_route().mcp
        self.assertIs(contract.read_only_hint, True)
        self.assertIs(contract.destructive_hint, False)
        schema = contract.input_schema
        self.assertEqual(set(schema["properties"]), {"kind", "type", "parameters"})
        self.assertEqual(schema["required"], ["kind"])
        self.assertNotIn("enum", schema["properties"]["type"])
        Draft202012Validator(schema).validate({"kind": "workflow_node", "type": "FUTURE_EXTENSION", "parameters": {}})


class AuthoringReferenceExtensionTests(SimpleTestCase):
    """Protect dynamic registry and port behavior without constructing runtime objects."""

    def read_reference(self, arguments: dict[str, Any]) -> dict[str, Any]:
        """Call the reader with permission granted while retaining real registry behavior."""
        request = HttpRequest()
        request.user = SimpleNamespace(is_authenticated=True)
        request.data = arguments
        with patch("bloomerp.views.mcp.get_authoring_reference.UserPolicyManager") as manager:
            manager.return_value.has_global_permission.return_value = True
            result = get_authoring_reference(request)
        self.assertIsInstance(result, dict)
        return result

    def register_node(self, key: str, executor: type[BaseExecutor]) -> None:
        """Install a temporary extension and remove it after the test."""
        WORKFLOW_NODE_REGISTRY.register(key, WorkflowNodeDefinition(
            id=key, type="FLOW", name="Extension", description="Extension routing.", executor_cls=executor,
        ))
        self.addCleanup(WORKFLOW_NODE_REGISTRY.unregister, key)

    def test_next_read_includes_new_types_without_runtime_construction(self) -> None:
        """Use case: Extensions are installed after a previous discovery call.
        Expected result: Indexes and targeted reads include them without executing defaults.
        """
        tile_before = self.read_reference({"kind": "tile"})
        node_before = self.read_reference({"kind": "workflow_node"})
        TILE_TYPE_REGISTRY.register("TARGETED_EXTENSION", TileTypeDefinition(
            name="Extension", description="Extension tile.", model=ReferenceExtensionTile,
        ))
        self.addCleanup(TILE_TYPE_REGISTRY.unregister, "TARGETED_EXTENSION")
        self.register_node("TARGETED_THREE_PORTS", ReferenceExtensionExecutor)
        tile_after = self.read_reference({"kind": "tile"})
        node_after = self.read_reference({"kind": "workflow_node"})
        self.assertEqual(len(tile_after["types"]), len(tile_before["types"]) + 1)
        self.assertEqual(len(node_after["types"]), len(node_before["types"]) + 1)
        tile = self.read_reference({"kind": "tile", "type": "TARGETED_EXTENSION"})
        self.assertEqual(tile["definition"]["config_schema"]["properties"]["content"]["type"], "string")
        node = self.read_reference({"kind": "workflow_node", "type": "TARGETED_THREE_PORTS"})["definition"]
        self.assertEqual(node["parameters"][0]["default_status"], "dynamic_not_evaluated")
        self.assertEqual(node["connections"]["output_port_schema"], {"type": "string", "enum": ["accepted", "review", "rejected"]})
        self.assertIs(node["connections"]["multiple_outputs"], True)
        self.assertEqual([port["max_connections"] for port in node["output_ports"]], [1, 2, None])

    def test_configured_ports_require_parameters_and_resolve_from_hook(self) -> None:
        """Use case: A new node determines its branches from saved parameters.
        Expected result: Missing parameters are explicit; supplied parameters resolve live ports.
        """
        self.register_node("TARGETED_CONFIGURED_PORTS", ConfiguredReferenceExecutor)
        arguments = {"kind": "workflow_node", "type": "TARGETED_CONFIGURED_PORTS"}
        unresolved = self.read_reference(arguments)["definition"]
        self.assertEqual(unresolved["connections"]["status"], "requires_parameters")
        self.assertIsNone(unresolved["connections"]["multiple_outputs"])
        self.assertEqual(unresolved["output_ports"], [])
        self.assertNotIn("enum", unresolved["connections"]["output_port_schema"])
        configured = self.read_reference({**arguments, "parameters": {"branches": ["north", "south", "west"]}})["definition"]
        self.assertEqual(configured["connections"]["status"], "resolved_from_parameters")
        self.assertEqual(configured["connections"]["output_port_schema"], {"type": "string", "enum": ["north", "south", "west"]})
        self.assertIs(configured["connections"]["multiple_outputs"], True)

    def test_incomplete_port_parameters_return_an_actionable_error(self) -> None:
        """Return a parameters error when an extension requires a missing configuration key."""
        self.register_node("TARGETED_REQUIRED_BRANCHES", ConfiguredReferenceExecutor)
        request = HttpRequest()
        request.user = SimpleNamespace(is_authenticated=True)
        request.data = {
            "kind": "workflow_node", "type": "TARGETED_REQUIRED_BRANCHES", "parameters": {},
        }
        with patch("bloomerp.views.mcp.get_authoring_reference.UserPolicyManager") as manager:
            manager.return_value.has_global_permission.return_value = True
            result = get_authoring_reference(request)
        self.assertEqual(result.status_code, 400)
        self.assertIn("parameters", result.data)

    def test_no_configured_ports_produces_a_valid_closed_connection_schema(self) -> None:
        """Describe an extension with no configured branches without an invalid empty enum."""
        self.register_node("TARGETED_NO_BRANCHES", ConfiguredReferenceExecutor)
        result = self.read_reference({
            "kind": "workflow_node", "type": "TARGETED_NO_BRANCHES", "parameters": {"branches": []},
        })["definition"]
        schema = result["connections"]["output_port_schema"]
        Draft202012Validator.check_schema(schema)
        self.assertFalse(Draft202012Validator(schema).is_valid("default"))
        self.assertEqual(result["output_ports"], [])
        self.assertIs(result["connections"]["multiple_outputs"], False)
